			dw kw_aset, arr_vector3d_py, var_vector3d_np, var_vector3d_addpoint_y
			dw kw_aset, arr_vector3d_pz, var_vector3d_np, var_vector3d_addpoint_z

			; Vector3D.cls 39: AddPoint = np
